def describe_strings(strings):
    output = []
    for s in strings:
        length = 0
        for _ in s:
            length += 1
        reversed_s = ''
        for i in range(length - 1, -1, -1):
            reversed_s = reversed_s + s[i]
        output.append((s, length, reversed_s))
    return output

print(describe_strings(['cat', 'dog']))

