def filter_valid_emails(emails):
    valid = []
    for email in emails:
        if email.count('@') == 1:
            parts = email.split('@')
            if len(parts) == 2 and '.' in parts[1]:
                valid.append(email.lower())
    return valid

print(filter_valid_emails(['Alice@Example.com', 'bad@@email.com', 'noat.com']))

def perfect_square_strings(values):
    def is_square(n):
        if n < 0:
            return False
        root = int(n ** 0.5)
        return root * root == n
    return (str(v) for v in values if isinstance(v, int) and is_square(v))

print(list(perfect_square_strings([1, 2, 4, 5, 9, 10])))
